# -*- coding: utf-8 -*-
"""dpr_rollback_v650_to_v649.py — R-1002-26 回滾程式（2026-10-07·R-1007-21）
用法：python3 dpr_rollback_v650_to_v649.py dpr_suite.py dpr_suite_v649.py
輸入 v650（SHA256 b72e63db…）→ 輸出 v649（SHA256 24361c94…·逐位元組）。
v650 只動三處：docstring 首段、SUITE_VERSION、_PACK 的 tdt_link（v6→v5）。"""
import sys,json,base64,lzma,hashlib
SRC_SHA='b72e63db65d43674e3e237d34b2ec8e247e11d8ccfcc2ba5249c977dbe98d6da'
DST_SHA='24361c94c2ce26d5026897c361764d4a1d250ceb3e3f9655c9b4759c295547be'
E=json.loads(lzma.decompress(base64.b64decode('')).decode())
src,dst=sys.argv[1],sys.argv[2]
raw=open(src,'rb').read()
assert hashlib.sha256(raw).hexdigest()==SRC_SHA,'輸入不是 v650'
L=raw.decode('utf-8').splitlines(True)
for j1,j2,old in sorted(E,key=lambda e:-e[0]):
    L[j1:j2]=[old]
out=''.join(L).encode('utf-8')
h=hashlib.sha256(out).hexdigest()
open(dst,'wb').write(out)
print(h, '✅ v649' if h==DST_SHA else '❌ 不符')
